def brackets_balanced(s: str) -> bool:
    stack = []
    matching = {")": "(", "]": "[", "}": "{"}
    in_string = False
    escaped = False

    for char in s:
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
        else:
            if char == '"':
                in_string = True
            elif char in "([{":
                stack.append(char)
            elif char in ")]}":
                if not stack or stack[-1] != matching[char]:
                    return False
                stack.pop()

    # If a string is unterminated, or if there are unmatched opening brackets
    if in_string or stack:
        return False

    return True
